-- Retire Contributor privileges without deleting accounts or legacy enum values.
CREATE OR REPLACE FUNCTION public.is_editor(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') $$;
CREATE OR REPLACE FUNCTION public.can_edit_job(_job_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.jobs WHERE id=_job_id) $$;
ALTER POLICY "editors or owner read jobs" ON public.jobs USING (public.is_editor(auth.uid()));
ALTER POLICY "editors insert jobs" ON public.jobs WITH CHECK (created_by=auth.uid() AND public.is_editor(auth.uid()));
ALTER POLICY "read own or editor cars" ON public.cars USING (public.is_editor(auth.uid()) OR owner_id=auth.uid());
ALTER POLICY "team read profiles" ON public.profiles USING (public.is_editor(auth.uid()) OR id=auth.uid());
ALTER POLICY "team read roles" ON public.user_roles USING (public.is_editor(auth.uid()) OR user_id=auth.uid());
ALTER POLICY "team read assignees" ON public.job_assignees USING (public.is_editor(auth.uid()));
ALTER POLICY "read vehicles" ON public.vehicles USING (public.is_editor(auth.uid()));
ALTER POLICY "editors insert vehicles" ON public.vehicles WITH CHECK (public.is_editor(auth.uid()));
ALTER POLICY "editors update vehicles" ON public.vehicles USING (public.is_editor(auth.uid())) WITH CHECK (public.is_editor(auth.uid()));
ALTER POLICY "editors delete vehicles" ON public.vehicles USING (public.is_editor(auth.uid()));
CREATE OR REPLACE FUNCTION public.validate_active_role() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.role='contributor' THEN RAISE EXCEPTION 'Contributor is retired; choose Admin or Client'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_active_role BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.validate_active_role();
ALTER TABLE public.cars ADD COLUMN photo_path text;
ALTER TABLE public.jobs ADD COLUMN internal_status text NOT NULL DEFAULT 'received', ADD COLUMN mechanical_setup text, ADD COLUMN objective text, ADD COLUMN validated_file_id uuid REFERENCES public.job_files(id) ON DELETE RESTRICT;
CREATE TABLE public.job_progress (job_id uuid PRIMARY KEY REFERENCES public.jobs(id) ON DELETE CASCADE, public_status text NOT NULL DEFAULT 'received', completed_steps text[] NOT NULL DEFAULT '{}', message text, information_request text, final_report text, report_released boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_progress TO authenticated;
GRANT ALL ON public.job_progress TO service_role;
ALTER TABLE public.job_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin manage progress" ON public.job_progress FOR ALL TO authenticated USING (public.is_editor(auth.uid())) WITH CHECK (public.is_editor(auth.uid()));
CREATE POLICY "owner read progress" ON public.job_progress FOR SELECT TO authenticated USING (public.owns_job(job_id));
CREATE TABLE public.job_reports (job_id uuid PRIMARY KEY REFERENCES public.jobs(id) ON DELETE CASCADE, content text NOT NULL DEFAULT '', released boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_reports TO authenticated;
GRANT ALL ON public.job_reports TO service_role;
ALTER TABLE public.job_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin manage reports" ON public.job_reports FOR ALL TO authenticated USING (public.is_editor(auth.uid())) WITH CHECK (public.is_editor(auth.uid()));
CREATE POLICY "owner released report" ON public.job_reports FOR SELECT TO authenticated USING (released AND public.owns_job(job_id));
COMMENT ON COLUMN public.job_progress.final_report IS 'DEPRECATED: report drafts belong in job_reports; never populate this column';
COMMENT ON COLUMN public.job_progress.report_released IS 'DEPRECATED: release flag belongs in job_reports';
CREATE TABLE public.job_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,actor_id uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),event text NOT NULL,details jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT ON public.job_history TO authenticated;
GRANT ALL ON public.job_history TO service_role;
ALTER TABLE public.job_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin read history" ON public.job_history FOR SELECT TO authenticated USING(public.is_editor(auth.uid()));
CREATE POLICY "admin private observation" ON public.job_history FOR INSERT TO authenticated WITH CHECK(public.is_editor(auth.uid()) AND actor_id=auth.uid() AND event='private_observation');
CREATE OR REPLACE FUNCTION public.audit_job_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.job_history(job_id,event,details) VALUES(CASE WHEN TG_TABLE_NAME='jobs' THEN NEW.id ELSE NEW.job_id END,TG_TABLE_NAME||'_'||lower(TG_OP),jsonb_build_object('before',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,'after',to_jsonb(NEW))); RETURN NEW; END $$;
CREATE TRIGGER audit_job_update AFTER UPDATE ON public.jobs FOR EACH ROW WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION public.audit_job_change();
CREATE TRIGGER audit_progress AFTER INSERT OR UPDATE ON public.job_progress FOR EACH ROW EXECUTE FUNCTION public.audit_job_change();
CREATE TRIGGER audit_report AFTER INSERT OR UPDATE ON public.job_reports FOR EACH ROW EXECUTE FUNCTION public.audit_job_change();
CREATE OR REPLACE FUNCTION public.validate_progress() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.public_status NOT IN ('received','analysis','development','testing','validation','completed') OR NOT NEW.completed_steps <@ ARRAY['received','analysis','development','testing','validation','completed']::text[] THEN RAISE EXCEPTION 'Invalid public progress'; END IF; IF NEW.final_report IS NOT NULL OR NEW.report_released THEN RAISE EXCEPTION 'Use the protected reports table'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_progress BEFORE INSERT OR UPDATE ON public.job_progress FOR EACH ROW EXECUTE FUNCTION public.validate_progress();
ALTER TABLE public.job_files ADD COLUMN format text, ADD COLUMN sha256 text;
ALTER TABLE public.file_logs ADD COLUMN format text, ADD COLUMN sha256 text;
CREATE TABLE public.test_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),file_id uuid NOT NULL REFERENCES public.job_files(id) ON DELETE CASCADE,recorded_at timestamptz NOT NULL DEFAULT now(),conditions text NOT NULL DEFAULT '',results text NOT NULL DEFAULT '',observations text NOT NULL DEFAULT '',created_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.test_sessions TO authenticated;
GRANT ALL ON public.test_sessions TO service_role;
ALTER TABLE public.test_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin manage tests" ON public.test_sessions FOR ALL TO authenticated USING(public.is_editor(auth.uid())) WITH CHECK(public.is_editor(auth.uid()) AND created_by=auth.uid());
CREATE TABLE public.file_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),file_id uuid NOT NULL REFERENCES public.job_files(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),actor_id uuid DEFAULT auth.uid(),details jsonb NOT NULL);
GRANT SELECT ON public.file_history TO authenticated;
GRANT ALL ON public.file_history TO service_role;
ALTER TABLE public.file_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin file history" ON public.file_history FOR SELECT TO authenticated USING(public.is_editor(auth.uid()));
CREATE OR REPLACE FUNCTION public.validate_technical_file() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE expected_prefix text; j uuid; BEGIN IF TG_TABLE_NAME='job_files' THEN j=NEW.job_id; expected_prefix=j::text||'/'; IF TG_OP='UPDATE' AND (NEW.path IS DISTINCT FROM OLD.path OR NEW.job_id IS DISTINCT FROM OLD.job_id OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.sha256 IS DISTINCT FROM OLD.sha256 OR NEW.size IS DISTINCT FROM OLD.size OR NEW.file_name IS DISTINCT FROM OLD.file_name OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by) THEN RAISE EXCEPTION 'File versions are immutable; upload a new version'; END IF; ELSE SELECT job_id INTO j FROM public.job_files WHERE id=NEW.file_id; expected_prefix=j::text||'/logs/'||NEW.file_id::text||'/'; IF TG_OP='UPDATE' AND (NEW.path IS DISTINCT FROM OLD.path OR NEW.file_id IS DISTINCT FROM OLD.file_id OR NEW.sha256 IS DISTINCT FROM OLD.sha256 OR NEW.file_name IS DISTINCT FROM OLD.file_name OR NEW.size IS DISTINCT FROM OLD.size) THEN RAISE EXCEPTION 'Log content is immutable'; END IF; END IF; IF NEW.path NOT LIKE expected_prefix||'%' OR position('..' in NEW.path)>0 THEN RAISE EXCEPTION 'Invalid file association'; END IF; IF TG_OP='INSERT' AND (NEW.size IS NULL OR NEW.size<=0 OR NEW.size>52428800 OR NEW.sha256 IS NULL OR NEW.sha256 !~ '^[a-f0-9]{64}$') THEN RAISE EXCEPTION 'Invalid file size or SHA-256'; END IF; IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='ecu-files' AND name=NEW.path AND (metadata->>'size')::bigint=NEW.size) THEN RAISE EXCEPTION 'Upload the matching object first'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_job_file BEFORE INSERT OR UPDATE ON public.job_files FOR EACH ROW EXECUTE FUNCTION public.validate_technical_file();
CREATE TRIGGER validate_file_log BEFORE INSERT OR UPDATE ON public.file_logs FOR EACH ROW EXECUTE FUNCTION public.validate_technical_file();
CREATE OR REPLACE FUNCTION public.audit_file_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.file_history(file_id,details) VALUES(NEW.id,jsonb_build_object('before',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,'after',to_jsonb(NEW))); RETURN NEW; END $$;
CREATE TRIGGER audit_file AFTER INSERT OR UPDATE ON public.job_files FOR EACH ROW EXECUTE FUNCTION public.audit_file_change();
CREATE OR REPLACE FUNCTION public.protect_original_file() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.kind='original' THEN RAISE EXCEPTION 'Original reads are protected from deletion'; END IF; RETURN OLD; END $$;
CREATE TRIGGER protect_original_file BEFORE DELETE ON public.job_files FOR EACH ROW EXECUTE FUNCTION public.protect_original_file();
ALTER POLICY "editors delete ecu" ON storage.objects USING(bucket_id='ecu-files' AND public.can_edit_job(((storage.foldername(name))[1])::uuid) AND NOT EXISTS(SELECT 1 FROM public.job_files WHERE path=name AND kind='original') AND NOT EXISTS(SELECT 1 FROM public.jobs j JOIN public.job_files f ON f.id=j.validated_file_id WHERE f.path=name));
CREATE OR REPLACE FUNCTION public.validate_job_configuration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.internal_status NOT IN ('received','diagnosis','analysis','calibration','testing','validation','completed','suspended') THEN RAISE EXCEPTION 'Invalid internal status'; END IF; IF NEW.validated_file_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.job_files WHERE id=NEW.validated_file_id AND job_id=NEW.id AND kind='modified') THEN RAISE EXCEPTION 'Validated version must be a modified file of this job'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_job_configuration BEFORE INSERT OR UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.validate_job_configuration();
CREATE POLICY "owner or admin read vehicle photo" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='vehicle-photos' AND EXISTS(SELECT 1 FROM public.cars WHERE id::text=(storage.foldername(name))[1] AND (owner_id=auth.uid() OR public.is_editor(auth.uid()))));
COMMENT ON TABLE public.job_assignees IS 'Legacy assignments retained; technical access is Admin only';
